const aiResponse = $input.first()?.json ?? {};

const text =
  aiResponse?.message?.content ||
  aiResponse?.choices?.[0]?.message?.content ||
  aiResponse?.text ||
  aiResponse?.content ||
  '';

function extractLine(label) {
  const match = text.match(new RegExp(`^${label}:\\s*(.*)$`, 'mi'));
  return match ? match[1].trim() : '';
}

const score = extractLine('SCORE');
const total = extractLine('TOTAL');
const weak_areas = extractLine('WEAK_AREAS');
const feedback = extractLine('FEEDBACK');

const leadNode = $('Lookup Lead in Sheets1').first();
const formNode = $('Parse Form Submission1').first();

if (!leadNode?.json) {
  throw new Error('No lead found from Lookup Lead in Sheets1');
}

if (!formNode?.json) {
  throw new Error('No parsed form found from Parse Form Submission1');
}

const lead = leadNode.json;
const form = formNode.json;

// wa.me must not include +
const whatsappNumber = '14155238886';
const waMsg = encodeURIComponent(`START:${lead.lead_id}`);
const trial_link = `https://wa.me/${whatsappNumber}?text=${waMsg}`;

return [
  {
    json: {
      lead_id: lead.lead_id || '',
      child_name: lead.child_name || '',
      child_age: lead.child_age || '',
      year_group: lead.year_group || '',
      subject: lead.subject || '',
      course: lead.course || '',
      availability: lead.availability || '',
      preference: lead.preference || '',
      challenges: lead.challenges || '',
      email: lead.email || '',
      contact_no: lead['contact no'] || lead.contact_no || '',

      score: score || '',
      total_marks: total || '',
      weak_areas: weak_areas || '',
      ai_feedback: feedback || '',
      qa_json: JSON.stringify(form.assessment?.questions || []),
      submitted_at: form.assessment?.submitted_at || '',

      trial_link
    }
  }
];

const item = $input.first().json;
const root = item.body ?? item;

// lead_id / submission_id at top level OR inside previous qa_json
const lead_id = root.lead_id ?? root.lead ?? root.qa_json?.lead_id ?? '';
const submission_id = root.submission_id ?? root.qa_json?.submission_id ?? null;

if (!lead_id) throw new Error('lead_id missing');
if (!submission_id) throw new Error('submission_id missing');

// This is where your questions actually are:
const quizObj = root.qa_json?.quiz_id ?? root.quiz_id ?? {};
const questionsRaw = quizObj?.["1"];   // array of question objects

if (!Array.isArray(questionsRaw) || questionsRaw.length === 0) {
  throw new Error('No questions found at quiz_id["1"]');
}

// helper: decode basic html entities (enough for your data)
function decodeHtml(s) {
  if (!s) return s;
  return String(s)
    .replaceAll('&amp;', '&')
    .replaceAll('&quot;', '"')
    .replaceAll('&#039;', "'")
    .replaceAll('&lt;', '<')
    .replaceAll('&gt;', '>');
}

// Extract student info (optional)
let student_name = null;
let email = null;
if (Array.isArray(quizObj.contact)) {
  for (const c of quizObj.contact) {
    if (c?.use === 'name' && !student_name) student_name = c.value;
    if (c?.use === 'email' && !email) email = c.value;
  }
}

// Convert each question object into a normalized structure
const questions = questionsRaw.map((q) => {
  const question = decodeHtml(q.question_title ?? q["0"] ?? '');

  // options are numeric keys except "0"
  const options = {};
  for (const [k, v] of Object.entries(q)) {
    if (/^\d+$/.test(k) && k !== '0' && typeof v === 'string' && v.trim()) {
      options[k] = decodeHtml(v.trim());
    }
  }

  // user_answer can be object like {"3":"divies"} or [] when unanswered
  let student_index = null;
  let student_text = null;
  if (q.user_answer && !Array.isArray(q.user_answer) && typeof q.user_answer === 'object') {
    const idx = Object.keys(q.user_answer)[0];
    if (idx) {
      student_index = idx;
      student_text = decodeHtml(q.user_answer[idx]);
    }
  }

  // correct_answer can be object {"1":"devise"} or array ["Weak"]
  let correct_index = null;
  let correct_text = null;
  if (Array.isArray(q.correct_answer)) {
    correct_text = decodeHtml(q.correct_answer[0] ?? null);
  } else if (q.correct_answer && typeof q.correct_answer === 'object') {
    const idx = Object.keys(q.correct_answer)[0];
    if (idx) {
      correct_index = idx;
      correct_text = decodeHtml(q.correct_answer[idx]);
    }
  }

  // Determine correctness (prefer q.correct field if present)
  const status = (q.correct ?? '').toString().toLowerCase(); // "correct"/"incorrect"
  const is_correct = status === 'correct';

  return {
    id: q.id ?? null,
    topic: q.category ?? null,
    question_type: q.question_type ?? null,
    question,
    options,
    student_answer: { index: student_index, text: student_text },
    correct_answer: { index: correct_index, text: correct_text },
    is_correct,
    points: q.points ?? null,
  };
});

// Mark as hasQA if we have at least one question with non-empty question text
const hasQA = questions.some(x => (x.question || '').trim().length > 0);

// Final clean JSON for AI
const assessment = {
  lead_id,
  submission_id,
  quiz_id: quizObj["0"] ?? null, // you had quiz_id.0 = 18
  submitted_at: root.qa_json?.submitted_at ?? root.submitted_at ?? new Date().toISOString(),
  student: { name: student_name, email },
  totals: {
    total_possible_points: quizObj.total_possible_points ?? null,
    total_attempted_questions: quizObj.total_attempted_questions ?? null,
    minimum_possible_points: quizObj.minimum_possible_points ?? null,
  },
  questions,
};

return [{
  json: {
    hasQA,
    assessment
  }
}];

const aiResponse = $input.first().json;

const roadmap_text =
