const sessionId = $json.sessionId;
const isStart = $json.isStart;

const workflowStaticData = $getWorkflowStaticData('global');

let leadId = $json.leadId;

if (isStart && leadId) {
  workflowStaticData[sessionId] = { leadId };
} else {
  const saved = workflowStaticData[sessionId];
  leadId = saved?.leadId || '';
}

return [{
  json: {
    ...$json,
    leadId,
    hasLeadId: !!leadId,
  }
}];

// Get lead data from Parse & Build Lead1
const lead = $('Parse & Build Lead').first().json;

// Get assessment link from the lookup result
const lookup = $input.first().json;

// Build assessment link with lead_id
const baseLink = lookup.assessment_link || '';
const assessmentLinkWithLead = baseLink
  ? `${baseLink}?lead_id=${lead.lead_id}`
  : '';

// Merge them together
return [{
  json: {
    lead_id: lead.lead_id,
    timestamp: lead.timestamp,
    child_name: lead.child_name,
    child_age: lead.child_age,
    year_group: lead.year_group,
    subject: lead.subject,
