  }
}];

const item = $input.first();
const output =
  item.json?.output ||
  item.json?.text ||
  item.json?.message?.content ||
  item.json?.response ||
  JSON.stringify(item.json) ||
  '';

const hasCollectedData = output.includes('COLLECTED_DATA:') && output.includes('END_COLLECTED_DATA');

return [{
  json: {
    ...item.json,
    output: output,
    hasCollectedData: hasCollectedData
  }
}];

// Extract fields from plain-text COLLECTED_DATA block
const output = $input.first().json.output || '';

const blockMatch = output.match(/COLLECTED_DATA:([\s\S]*?)END_COLLECTED_DATA/);
if (!blockMatch) {
  throw new Error('COLLECTED_DATA block not found. Agent output was: ' + output.substring(0, 400));
}

const block = blockMatch[1].trim();

function extract(key) {
  const match = block.match(new RegExp(key + ':\\s*(.+)'));
  return match ? match[1].trim() : '';
}

const child_name     = extract('child_name');
const child_age      = extract('child_age');
const year_group     = extract('year_group');
const subject        = extract('subject');
const course         = extract('course');
const availability   = extract('availability');
const preference     = extract('preference');
const challenges     = extract('challenges');
const email          = extract('email');
const contact_no     = extract('contact_no');

// Generate Lead ID
const lead_id = 'LEAD-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6).toUpperCase();
const timestamp = new Date().toISOString();

return [{
  json: {
    lead_id,
    timestamp,
    child_name,
    child_age,
    year_group,
    subject,
    course,
    availability,
    preference,
    challenges,
    assessment_sent: false,
    status: 'Enquiry',
    email,
    contact_no
  }
}];

