const lead = $items("Parse & Build Lead1")[0].json; // <-- this node MUST have executed
const lookup = $input.first().json;

const baseLink = lookup.assessment_link || '';
const separator = baseLink.includes('?') ? '&' : '?';

const assessmentLinkWithLead = baseLink
  ? `${baseLink}${separator}lead_id=${encodeURIComponent(lead.lead_id)}`
  : '';

return [{
  json: {
    ...lead,
    assessment_link: assessmentLinkWithLead,
  }
}];

// n8n Code node (JavaScript)

const item = $input.first().json;
const body = item.body ?? item ?? {};

function get(key, fallback = '') {
  const v = body?.[key];
  if (v === undefined || v === null) return fallback;
  return String(v).trim();
}

// Convert Yes/No to boolean
function toBool(v, defaultValue = false) {
  if (v === undefined || v === null || v === '') return defaultValue;
  if (typeof v === 'boolean') return v;

  const s = String(v).trim().toLowerCase();
  if (['yes', 'true', '1'].includes(s)) return true;
  if (['no', 'false', '0'].includes(s)) return false;

  return defaultValue;
}

// Lead ID (use incoming if exists)
const incomingLeadId = get('lead_id', '');
const lead_id =
  incomingLeadId ||
  `LEAD-${Date.now()}-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;

const timestamp = get('timestamp', new Date().toISOString());

// Extract fields
const child_name     = get('child_name');
const child_age      = get('child_age');
const year_group     = get('year_group');
const subject        = get('subject');
const course         = get('course');
const availability   = get('availability');
const preference     = get('preference');
const challenges     = get('challenges');
const email          = get('email');
const contact_no     = get('contact_no');

const assessment_sent = toBool(body.assessment_sent, false);
const status = get('status', 'New');

return [
  {
    json: {
      lead_id,
      timestamp,
      child_name,
      child_age,
      year_group,
      subject,
      course,
      availability,
      preference,
      challenges,
      assessment_sent,
      status,
      email,
      contact_no
    }
  }
];

const outcomes = $input.all()
  .flatMap(i => {
    const raw = i.json.course_outcome ?? i.json.outcome ?? '';
    return String(raw)
      .split(/\r?\n|,/g)     // split by newline OR comma
      .map(x => x.trim())
      .filter(Boolean);
  });

const unique = [...new Set(outcomes)];
const course_outcomes_text = unique.map(o => `- ${o}`).join('\n');

return [{
  json: {
    course_outcomes: unique,
    course_outcomes_text: course_outcomes_text
  }
}];

const output = $input.first().json.output || "";

// Remove newlines and problematic characters for safe JSON embedding
const clean = output
  .replace(/\\/g, "\\\\")   // escape backslashes first
  .replace(/"/g, '\\"')      // escape double quotes
  .replace(/\n/g, "\\n")    // escape newlines
  .replace(/\r/g, "")       // remove carriage returns
  .replace(/\t/g, " ");     // replace tabs with space

return [{ json: { reply: clean } }];

const raw = $json.output;

const cleaned = raw
  .replace(/\\n/g, '\n')        // Convert literal \n to real newlines
  .replace(/&/g, '&amp;');      // Escape & for XML

return { cleaned };

const snippet = $input.item.json.snippet || '';

// Amount
const amountMatch = snippet.match(/([\d.]+)\s*(GBP|BDT|USD|EUR)/i);
const amount = amountMatch ? amountMatch[0] : 'N/A';

// Reference
const refMatch = snippet.match(/Reference[:\s]+([A-Za-z0-9\-]+)/i);
const reference = refMatch ? refMatch[1].trim() : '';

// Sender name
const nameMatch = snippet.match(/received\s+[\d.]+\s+\w+\s+from\s+([A-Z\s]+?)(?:\.|And|$)/i);
const senderName = nameMatch ? nameMatch[1].trim() : 'Guardian';

// Date
const date = new Date().toLocaleDateString('en-GB');

return [{ json: { amount, reference, senderName, date } }];
